-- 02-order.sql
-- 本地 prod-split 真实演示 seed，仅供联调，不属于生产迁移。
-- target database: omni_order


BEGIN;
-- STATUS_PAID=2, STATUS_CANCELLED=3, STATUS_REFUNDED=4；支付超时以取消订单演示。
DELETE FROM electronic_ticket WHERE order_id BETWEEN 980001 AND 980999;
DELETE FROM order_seat WHERE order_id BETWEEN 980001 AND 980999;
DELETE FROM order_snapshot WHERE order_id BETWEEN 980001 AND 980999;
DELETE FROM "order" WHERE id BETWEEN 980001 AND 980999;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, amount = EXCLUDED.amount, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET activity_name = EXCLUDED.activity_name, activity_poster = EXCLUDED.activity_poster, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, update_time = EXCLUDED.update_time;

SELECT setval('order_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM "order"), 1), 1), true);
SELECT setval('order_seat_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM order_seat), 1), 1), true);
SELECT setval('order_snapshot_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM order_snapshot), 1), 1), true);
SELECT setval('electronic_ticket_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM electronic_ticket), 1), 1), true);
COMMIT;